import type { JsonValue, Subject } from "./state.js";

export interface SubmitCommand {
  type: "submit";
  /** Generated by the service with the injected id generator. */
  requestId: string;
  requesterId: string;
  subject: Subject;
  payload: JsonValue;
  tenantId?: string;
}

export interface ApproveCommand {
  type: "approve";
  requestId: string;
  actorId: string;
  comment?: string;
}

export interface RejectCommand {
  type: "reject";
  requestId: string;
  actorId: string;
  comment?: string;
}

export type Command = SubmitCommand | ApproveCommand | RejectCommand;
